def forward(groups):
    interconnect = groups[0]
    expanded = groups[1]
    return {'stored': [int(expanded.split(':')[0]), int(expanded.split(':')[1]), int(expanded.split(':')[2])], 'layout': [interconnect]}

def inverse(record):
    interconnect = record['layout'][0]
    expanded = f"{record['stored'][0]}:{record['stored'][1]}:{record['stored'][2]}"
    return f"Interconnect-{interconnect}:{expanded}"
